import React, { useState } from 'react'
import { Button, Modal } from 'antd'
import { ModelBodyStyleWrapper } from './index.style'

const CustomModal = (props) => {
  const [visible, setVisible] = useState(false)

  const showModel = () => {
    setVisible(true)
  }
  const handleCancel = () => {
    setVisible(false)
  }

  return (
    <div>
      <Button onClick={showModel}> {props.buttonTitle} </Button>
      <Modal
        className='model-class'
        title={props.modalTitle}
        visible={visible}
        onCancel={handleCancel}
        footer={null}
      >
        <ModelBodyStyleWrapper>
          {props.children}
        </ModelBodyStyleWrapper>

      </Modal>
    </div>
  )
}
export default CustomModal
