import React from 'react'
import { Row, Col } from 'antd'
import { AlertStyled } from './alert.style'

export default class Alert extends React.PureComponent {
  render () {
    var { message } = this.props
    let index = message.indexOf(':')
    message = message.substring((index + 1), message.length)
    return (
      <AlertStyled>
        <div className='reminder-warning'>
          <Row type='flex' justify='center' align='middle'>
            <Col xs={24} sm={24} md={3} className='container-icon'>
              <div className='reminder-icon-warning'>
                <i className='fas fa-bell' />
              </div>
            </Col>
            <Col xs={24} sm={24} md={21} className='notification-content'>
              <p className='reminder-heading'>Maximum Limit Reached</p>
              <p className='reminder-subheading'>
                {message}
              </p>
            </Col>
          </Row>
        </div>
      </AlertStyled>
    )
  }
}
