import { Button, Form, Typography } from 'antd'
import { useState } from 'react'
import { QuestionsBtnWrapper } from './index.style.js'

const { Text } = Typography
const QuestionsData = (props) => {
  const [isYes, setIsYes] = useState('')
  const {
    data: { id = '', display_text: displayText = '' } = {},
    onHandleAddOnsDataChange
  } = props

  const handleChange = (id, flag) => {
    onHandleAddOnsDataChange(id, flag)
    if (flag) {
      setIsYes('true')
    } else {
      setIsYes('false')
    }
  }
  return (
    <div key={id}>
      <Text strong>{displayText}</Text>
      <QuestionsBtnWrapper>
        <Form.Item>
          <Button type={isYes === 'true' ? 'primary' : ''} onClick={() => handleChange(id, true)}>
            YES
          </Button>
        </Form.Item>
        <Form.Item>
          <Button type={isYes === 'false' ? 'primary' : ''} onClick={() => handleChange(id, false)}>NO</Button>
        </Form.Item>
      </QuestionsBtnWrapper>
    </div>
  )
}
export default QuestionsData
