import React from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import { QuestionsWrapper } from './index.style.js'
import { Alert, Spin } from 'antd'
import claimActions from '../../../../redux/claims/actions'
import QuestionsData from './add-questions-content.js'
import { showNotification } from '../../../../../components/ShowNotification/index.js'

const { getQuestionsList, resetReduxStateClaim } = claimActions

class AddOnsContent extends React.Component {
  state = {
    questionsData: [],
    addOnQuestionsList: []
  };

  componentDidMount () {
    const {
      policyDetails: {
        Request: { additional_protection: addProtection = [] } = {}
      } = {},
      policyDetails,
      addOnQuestionsList,
      setdisableSubmitBtn = () => {}
    } = this.props

    if (
      policyDetails &&
      addProtection.length &&
      addOnQuestionsList.length === 0
    ) {
      const addOnsList = addProtection.map((addon) => addon.id, [])
      const payload = { addons: [...addOnsList] }
      this.props.getQuestionsList(payload)
    }
    setdisableSubmitBtn(false)
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      onHandleQuestionsChange = () => {},
      addOnQuestionsList = [],
      totalQuestionsListError = false,
      setdisableSubmitBtn = () => {}
    } = nextProps
    const updatedQuestionsList = addOnQuestionsList.map((item) => {
      return { id: item.id, response: false, display_text: item.display_text }
    }, [])
    const updatedQuestionsResponse = addOnQuestionsList.map((item) => {
      return { id: item.id, response: false }
    })
    this.setState({ questionsData: updatedQuestionsList })
    onHandleQuestionsChange(updatedQuestionsResponse)

    if (totalQuestionsListError) {
      showNotification('error', 'Error')
      setdisableSubmitBtn(true)
      this.props.resetReduxStateClaim(['addOnQuestionsList'])
    }
  }

  handleAddOnsDataChange = (id, flag) => {
    const updatedAddOnsData = this.state.questionsData.map((data) => {
      return data.id === id ? { ...data, response: flag } : data
    })
    const updatedQuestionsResponse = this.state.questionsData.map((data) => {
      return data.id === id
        ? { id, response: flag }
        : { id: data.id, response: data.response }
    })
    this.setState({ questionsData: updatedAddOnsData })
    this.props.onHandleQuestionsChange(updatedQuestionsResponse)
  };

  render () {
    const {
      addOnQuestionsList,
      questionsListLoading = true,
      totalQuestionsListError
    } = this.props
    return (
      <>
        <Spin spinning={!!questionsListLoading} tip='Please wait ...'>
          {totalQuestionsListError
            ? (
              <Alert
                message='There is an error in our system, please contact CS'
                type='error'
              />
              )
            : (
              <QuestionsWrapper>
                {addOnQuestionsList.map((questions, ind) => {
                  return (
                    <QuestionsData
                      key={ind + 1}
                      data={questions}
                      onHandleAddOnsDataChange={this.handleAddOnsDataChange}
                    />
                  )
                })}
                {addOnQuestionsList !== undefined &&
                addOnQuestionsList.length < 1 && (
                  <h3>Pertanyaan tidak ditemukan</h3>
                )}
              </QuestionsWrapper>
              )}
        </Spin>
      </>
    )
  }
}

AddOnsContent.propTypes = {
  questionsData: PropTypes.array
}

AddOnsContent.defaultProps = {
  questionsData: []
}

export default connect(
  (state) => ({
    addOnQuestionsList: state.Claims.addOnQuestionsList,
    totalQuestionsListError: state.Error.GET_LIST_QUESTIONS,
    questionsListLoading: state.Loading.GET_LIST_QUESTIONS
  }),
  {
    getQuestionsList,
    resetReduxStateClaim
  }
)(AddOnsContent)
