import React, { useState } from 'react'
import { TableContainer, StyledTable, TableHeader, TableRow, TableCell, PaginationContainer, PageButton, ActionButton } from './ClaimListStyles.style'

const ClaimListComponent = ({ tableData, methods, metaData }) => {
  const { detailFunction, claimListLoading, handleTable } = methods
  const claimData = tableData || []
  const claimMetaData = metaData || { page_size: 10, total_records: 0 }

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1)
  const pageSize = claimMetaData.page_size
  const totalPages = claimMetaData.num_page

  // Handle Pagination Change
  const handlePaginationChange = (newPage) => {
    setCurrentPage(newPage)
    handleTable({
      current: newPage,
      pageSize: pageSize
    }, {}, {})
  }

  return (
    <TableContainer>
      {claimListLoading
        ? (
          <p>Loading...</p>
          )
        : (
          <>
            <StyledTable>
              <thead>
                <TableRow>
                  <TableHeader>Claim No</TableHeader>
                  <TableHeader>Benefit</TableHeader>
                  <TableHeader>Created At</TableHeader>
                  <TableHeader>Status</TableHeader>
                  <TableHeader>Action</TableHeader>
                </TableRow>
              </thead>
              <tbody>
                {claimData.map((val, index) => (
                  <TableRow key={index}>
                    <TableCell>{val.claim_no}</TableCell>
                    <TableCell>{val.benefit}</TableCell>
                    <TableCell>{val.created_at}</TableCell>
                    <TableCell>{val.status}</TableCell>
                    <TableCell align='center'>
                      <ActionButton onClick={() => detailFunction(val.claim_id)}>Detail</ActionButton>
                    </TableCell>
                  </TableRow>
                ))}
              </tbody>
            </StyledTable>

            <PaginationContainer>
              <PageButton disabled={currentPage === 1} onClick={() => handlePaginationChange(currentPage - 1)}>Prev</PageButton>
              <span>Page {currentPage} of {totalPages}</span>
              <PageButton disabled={currentPage === totalPages} onClick={() => handlePaginationChange(currentPage + 1)}>Next</PageButton>
            </PaginationContainer>
          </>
          )}
    </TableContainer>
  )
}

export default ClaimListComponent
