import React, { Component } from 'react'
import { Form, Input, Button, Select, Spin } from 'antd'

import { PhoneNumberPrefix } from '../../../../helpers/constant'

const FormItem = Form.Item
const { Option } = Select

class ResendNotification extends Component {
  state = {
    deliveryId: ''
  }

  componentDidMount () {
    this.setState({ deliveryId: this.props.deliveryId })
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    if (nextProps.deliveryId !== this.state.deliveryId) {
      this.setState({ deliveryId: nextProps.deliveryId })
      this.props.form.resetFields()
    }
  }

  handleSubmit = (e) => {
    e.preventDefault()
    this.props.form.validateFields((error, values) => {
      if (!error) {
        this.props.resendTrigger(values)
      }
    })
  }

  render () {
    const { type, form, loading } = this.props
    const { getFieldDecorator } = form
    const prefixSelector = getFieldDecorator('prefix', {
      initialValue: '62'
    })(
      <Select>
        {PhoneNumberPrefix.map((prefix, index) => (
          <Option key={index} value={prefix.value}>{prefix.label}</Option>
        ))}
      </Select>
    )

    return (
      <Spin spinning={!!loading}>
        <Form onSubmit={this.handleSubmit}>
          <label>{`Enter ${type === 'email' ? 'Email' : 'Phone Number'}`}</label>
          <FormItem>
            {
              getFieldDecorator('recipient',
                {
                  rules: [
                    {
                      required: true,
                      message: 'Recipient tidak boleh kosong'
                    }
                  ]
                }
              )(
                type === 'email'
                  ? <Input type='email' />
                  : <Input type='number' addonBefore={prefixSelector} />
              )
            }
          </FormItem>
          <Button
            type='primary'
            htmlType='submit'
          >
            Resend
          </Button>
        </Form>
      </Spin>
    )
  }
}

const WrappedResendNotification = Form.create()(ResendNotification)

export default WrappedResendNotification
