import React from 'react'
import { connect } from 'react-redux'
import {
  Modal,
  Button,
  Radio,
  Spin,
  Col,
  Row,
  Alert,
  Collapse,
  Icon,
  Checkbox
} from 'antd'
import claimActions from '../../redux/claims/actions'
import AlertLimit from '../../../components/limitAlert'
import ClaimPopupWrapper from './ClaimPopup.style'
import ModalClaimConfirmation from './modalClaimConfirmation'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import PermissionCheckerV2 from '../../../components/permissionCheckerV2'
import AddOnsContent from './components/QuestionsList'

const Panel = Collapse.Panel
const RadioGroup = Radio.Group
const { getBenefits, validateClaim, createClaim, resetReduxStateClaim } = claimActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class ClaimPopup extends React.Component {
  state = {
    isClaimActive: false,
    loader: false,
    displaySafeMessage: false,
    skipPreCheck: false,
    showAddOnsQuestions: false,
    addOnsQuestions: [],
    disableSubmitBtn: false
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      dataValidate,
      claimValidateLoading,
      claimValidateError,
      claimValidateStatus,
      claimId,
      createClaimStatus,
      createClaimLoading,
      createClaimError
    } = nextProps
    const { history } = this.props
    if (!claimValidateLoading && !claimValidateError && claimValidateStatus) {
      const {
        message,
        claim_id: existingClaimdId,
        is_claimable: isClaimable,
        is_first_claim: isFirstClaim
      } = dataValidate
      if (!existingClaimdId && isFirstClaim) {
        this.createClaim()
      } else if (existingClaimdId) {
        history.push(`/claims/${existingClaimdId}`)
        this.props.resetReduxStateClaim()
      } else if (!existingClaimdId && !isFirstClaim && !isClaimable) {
        this.setState({
          displaySafeScreen: true
        })
        return
      } else {
        this.setState({
          showValidatePopup: true,
          validatePopupMessage: message
        })
      }
    }
    if (!createClaimLoading && !createClaimError && createClaimStatus && claimId) {
      history.push(`/claims/${claimId}`)
      this.props.resetReduxStateClaim()
    }
    if (!claimValidateLoading && claimValidateError && claimValidateStatus) {
      this.setState({ showAddOnsQuestions: false })
    }
    if (!createClaimLoading && !!createClaimError && createClaimStatus) {
      this.setState({ showAddOnsQuestions: false })
    }
  }

  componentWillUnmount () {
    this.props.resetReduxStateClaim()
  }

  componentDidMount () {
    const { product, packageName, isClaimOpen, partner, internalId, applicationNo } = this.props
    if (isClaimOpen && packageName !== undefined) {
      const strToLower = packageName.toLowerCase()
      const pkg = strToLower.replace(/' '/g, '-')
      this.props.getBenefits({ query: { package: pkg, product, partner, internal_id: internalId, application_no: applicationNo } })
    }
  }

  handleCancel = () => {
    this.props.resetReduxStateClaim()
    this.props.triggerClosePopup()
  }

  handleCancelClaimValidation = () => {
    this.setState({ showValidatePopup: false })
  }

  handleOkClaimValidation = () => {
    this.createClaim()
    this.handleCancelClaimValidation()
  }

  handleChange = (e) => {
    this.setState({
      value: e.target.value,
      btnLoading: false
    })
  }

  handleCheckChange = (e) => {
    this.setState({ skipPreCheck: e.target.checked })
  }

  createClaim = () => {
    const { isClaimActive, value, skipPreCheck, addOnsQuestions } = this.state
    const { policyDetails: { Request: { additional_protection: addProtection = [] } = {} } = {} } = this.props
    const { applicationNo } = this.props
    const body = addProtection.length
      ? {
          benefit_id: value,
          application_no: applicationNo,
          skip_precheck: skipPreCheck,
          source: 'control-panel',
          question_data: [...addOnsQuestions]
        }
      : {
          benefit_id: value,
          application_no: applicationNo,
          skip_precheck: skipPreCheck,
          source: 'control-panel'
        }
    if (isClaimActive) {
      this.props.createClaim({
        body
      })
      this.props.resetErrorRedux(['CLAIM_VALIDATE'])
      this.props.resetLoadingRedux(['CLAIM_VALIDATE'])
      this.props.resetReduxStateClaim(['claimValidateStatus'])
    } else {
      this.setState({ displaySafeMessage: true })
    }
  }

  handleValidate = () => {
    const { applicationNo } = this.props
    const { value } = this.state
    this.props.validateClaim({
      query: {
        benefitId: value,
        applicationNo
      }
    })
  }

  safeScreen = () => {
    return (
      <div>
        <h3>Anda dalam perlindungan yang tepat</h3>
        <p>Untuk info lebih lengkap hubungi customer service kami pada nomor di bawah ini &amp; daftarkan klaim anda</p>
        <span className='text-font-size-24'>
          <i className='fas fa-phone-volume' />&nbsp;&nbsp;021 3044 8080
        </span>
        <br />
        <br />
        - ATAU -
        <br />
        <br />
        <p>Chat dengan customer service kami melalu nomor whatsapp dibawah ini &amp; daftarkan klaim anda</p>
        <span className='text-font-size-24'>
          <i className='fab fa-whatsapp' /> &nbsp;&nbsp;0877 0017 8000
        </span>
      </div>
    )
  }

  onCloseDisplayError = () => {
    this.props.removeDisplayError()
  }

  genExtra = () => (
    <Icon type='down' />
  )

  isActive = status => {
    this.setState({ isClaimActive: status })
  }

  renderUnSafeScreen = (getBenefitsLoading, claimBenefitsData) => (
    <Spin spinning={!!getBenefitsLoading} tip='Loading...'>
      {
        (claimBenefitsData !== undefined && claimBenefitsData.length > 0) && (
          <RadioGroup
            onChange={this.handleChange}
            value={this.state.value}
            className='benefits-radio radioWrapperHeightAuto'
          >
            {
              claimBenefitsData.map((val, index) => {
                if (val.benefits.length > 1) {
                  return (
                    <Collapse key={index}>
                      <Panel
                        header={
                          <div className='benefits-collapse-header'>
                            <b>{val.benefit_group_name} </b>
                            <br />
                            <span>{val.benefit_group_description}</span>
                          </div>
                        }
                        key={index}
                        extra={this.genExtra()}
                      >
                        {
                          val.benefits.map((value, i) => {
                            return (
                              <Radio
                                key={i}
                                value={value.benefit_id}
                                onChange={() => this.isActive(value.is_claim_active)}
                              >
                                <b>{value.benefit_name}</b>
                              </Radio>
                            )
                          })
                        }
                      </Panel>
                    </Collapse>
                  )
                } else {
                  return val.benefits.map((value, i) => {
                    return (
                      <div key={i} className='radio-content-wrapper'>
                        <Radio
                          key={i}
                          value={value.benefit_id}
                          onChange={() => this.isActive(value.is_claim_active)}
                        >
                          <b>{value.benefit_name}</b>
                          <br />
                          <span className='description'>{value.description}</span>
                        </Radio>
                        <br />
                      </div>
                    )
                  })
                }
              })
            }
          </RadioGroup>
        )
      }
      {
        (claimBenefitsData !== undefined && claimBenefitsData.length < 1) && (
          <h3>Manfaat tidak ditemukan</h3>
        )
      }
    </Spin>
  )

  handleShowQuestionsDetail = () => {
    this.setState({ showAddOnsQuestions: true })
  }

  handleCloseAddOns = () => {
    this.setState({ showAddOnsQuestions: false })
  }

  handleQuestionsChange = (data) => {
    this.setState({ addOnsQuestions: data })
  }

  setdisableSubmitBtn = (flag) => {
    this.setState({ disableSubmit: flag })
  }

  render () {
    const {
      isClaimOpen,
      claimBenefitsData,
      createClaimStatus,
      getBenefitsLoading,
      claimValidateLoading,
      claimValidateError,
      claimValidateStatus,
      claimValidateStatusCode,
      createClaimLoading,
      createClaimError,
      policyDetails: { Request: { additional_protection: addProtection = [] } = {} } = {}
    } = this.props
    const {
      value,
      isClaimActive,
      showValidatePopup,
      validatePopupMessage,
      displaySafeScreen,
      skipPreCheck,
      disableSubmit
    } = this.state
    return (
      <>
        <ModalClaimConfirmation
          isOpen={showValidatePopup}
          message={validatePopupMessage}
          onOk={this.handleOkClaimValidation}
          onCancel={this.handleCancelClaimValidation}
          loading={createClaimLoading}
        />
        <Modal
          title={this.state.showAddOnsQuestions ? 'Please complete the questions below to speed up and simplify your claim process.' : 'Benefits'}
          visible={isClaimOpen}
          onCancel={this.handleCancel}
          maskClosable={false}
          closable={false}
          footer={[
            <Button key={1} onClick={this.handleCancel}>Cancel</Button>,
            <Button
              key={2}
              disabled={!value || !isClaimActive || claimValidateLoading || getBenefitsLoading || createClaimLoading || disableSubmit}
              onClick={(!this.state.showAddOnsQuestions && addProtection.length) ? this.handleShowQuestionsDetail : this.handleValidate}
              loading={claimValidateLoading || getBenefitsLoading || createClaimLoading}
            >
              {(!this.state.showAddOnsQuestions && addProtection.length) ? 'Next' : 'Claim'}
            </Button>
          ]}
          wrapClassName='benefits-modal'
        >
          {this.state.showAddOnsQuestions
            ? (
              <AddOnsContent
                policyDetails={this.props.policyDetails}
                onHandleCloseAddOns={this.handleCloseAddOns}
                onHandleQuestionsChange={this.handleQuestionsChange}
                setdisableSubmitBtn={this.setdisableSubmitBtn}
              />
              )
            : (
              <ClaimPopupWrapper>
                {!claimValidateLoading &&
                claimValidateError &&
                claimValidateStatus &&
                (claimValidateStatusCode === 'CLAIM_109'
                  ? (
                    <AlertLimit message={claimValidateStatus} />
                    )
                  : (
                    <Alert message={claimValidateStatus} type='error' />
                    ))}
                {value && !isClaimActive && (
                  <Alert
                    message='Claim is not active for this benefit'
                    type='error'
                  />
                )}
                {!createClaimLoading &&
                !!createClaimError &&
                createClaimStatus && (
                  <Row className='row-width'>
                    <Col span={24}>
                      <Alert message={createClaimStatus} type='error' />
                    </Col>
                  </Row>
                )}
                <Spin
                  spinning={
                  !!getBenefitsLoading ||
                  !!claimValidateLoading ||
                  !!createClaimLoading
                }
                  tip='Please wait ...'
                  className='loader-row'
                >
                  {displaySafeScreen
                    ? this.safeScreen()
                    : this.renderUnSafeScreen(
                      getBenefitsLoading,
                      claimBenefitsData
                    )}
                </Spin>
                <PermissionCheckerV2 requiredPermission='ops.claims_skip_precheck'>
                  <Checkbox
                    className='checkbox-margin'
                    defaultValue={skipPreCheck}
                    onChange={this.handleCheckChange}
                  >
                    Skip Precheck
                  </Checkbox>
                </PermissionCheckerV2>
              </ClaimPopupWrapper>
              )}
        </Modal>
      </>
    )
  }
}

export default connect(
  state => ({
    claimId: state.Claims.claimId,
    claimBenefitsData: state.Claims.claimBenefitsData,
    getClaimBenefitsStatus: state.Claims.getClaimBenefitsStatus,
    createClaimStatus: state.Claims.createClaimStatus,
    dataValidate: state.Claims.dataValidate,
    claimValidateStatus: state.Claims.claimValidateStatus,
    claimValidateStatusCode: state.Claims.claimValidateStatusCode,
    getBenefitsLoading: state.Loading.GET_BENEFITS,
    getBenefitsError: state.Error.GET_BENEFITS,
    claimValidateLoading: state.Loading.CLAIM_VALIDATE,
    claimValidateError: state.Error.CLAIM_VALIDATE,
    createClaimLoading: state.Loading.CREATE_CLAIM,
    createClaimError: state.Error.CREATE_CLAIM
  }),
  {
    getBenefits,
    resetReduxStateClaim,
    validateClaim,
    createClaim,
    resetLoadingRedux,
    resetErrorRedux
  }
)(ClaimPopup)
