import React, { Component } from 'react'
import { connect } from 'react-redux'
import { notification, Spin, Form, Row, Col, Checkbox, Button, DatePicker, Popconfirm, Input, InputNumber } from 'antd'
import policyActions from '../../../../../redux/policy/actions'
import { capitalizeFirstLetter } from '../../../../../helpers/utility'
import moment from 'moment-timezone'
import { getFormItems, errorHandler } from './forItems'
import FormStyleWrapper from './index.style'

const { TextArea } = Input

const { resetReduxState, editPolicyDetails } = policyActions
class PolicyEditForm extends Component {
  state = {
    policyAttributeData: {},
    editPolicyDetailCheckBox: false
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      policyAttributeData,
      // policyAttributeDataLoading,
      // policyAttributeDataError,
      editPolicyData,
      submitEditPolicyData,
      editPolicyDataMessage,
      policyEditAttributeDataMessage
    } = nextProps
    if (policyEditAttributeDataMessage === 'success') {
      this.setState({
        policyAttributeData: policyAttributeData
      })
      this.props.resetReduxState(['policyEditAttributeDataMessage'])
    }
    if (editPolicyDataMessage === 'success') {
      notification.success({
        message: 'Policy Edited Successfully',
        description: ''
      })
      this.props.cancelButton()
      this.props.reloadPage()
    }
    if (editPolicyDataMessage && editPolicyDataMessage !== 'success') {
      errorHandler.call(this, {
        submitError: submitEditPolicyData,
        detailMessage: editPolicyData.error,
        resetFunction: () => this.props.resetReduxState(['editPolicyDataMessage'])
      })
    }
    if ((editPolicyData.errors || editPolicyData.error) && editPolicyDataMessage && editPolicyDataMessage !== 'success') {
      notification.error({
        message: 'Error',
        description: editPolicyData.errors ? editPolicyData.errors[0].err : editPolicyData.error[0].err
      })
      this.props.resetReduxState(['editPolicyDataMessage'])
    }
  }

  onChangeCheckBoxHandler = (e) => {
    this.setState({
      editPolicyDetailCheckBox: e.target.checked
    })
  }

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const { dataProfile, policyId, policyAttributeData, policyDetail } = this.props
        const payload = {
          request: {},
          audit_id: `PP-${Math.floor(1000 + Math.random() * 9000)}${policyId}`,
          updated_by_user: dataProfile?.email ?? '',
          coverage_end: moment(values.coverage_end).format('YYYY-MM-DD HH:mm:ss'),
          coverage_start: moment(values.coverage_start).format('YYYY-MM-DD HH:mm:ss'),
          policy_premium: values.policy_premium ? Number(values.policy_premium) : '',
          remarks: values.remarks,
          enqueue_flag: values.enqueue_flag
          // endosement:{}
        }
        const requestSection = policyAttributeData?.request ?? {}
        const endorsementSection = policyAttributeData?.endorsement ?? {}
        for (const key in requestSection) {
          // TODO: verify below line is not breaking, changed by AJIT
          if (requestSection[key].field_type === 'datetime' && values[key]) {
            payload.request = { ...payload.request, [key]: moment(values[key]).format('YYYY-MM-DD HH:mm:ss') }
          } else if (requestSection[key].field_type === 'date' && values[key]) {
            payload.request = { ...payload.request, [key]: moment(values[key]).format('YYYY-MM-DD') }
          } else if (requestSection[key].field_type === 'year' && values[key]) {
            payload.request = { ...payload.request, [key]: moment(values[key]).format('YYYY') }
          } else {
            payload.request = { ...payload.request, [key]: values[key] }
          }
        }
        if ((Object.keys(endorsementSection).length > 0) && policyDetail.EndorsementStatus === 'SUCCESS') {
          for (const key in endorsementSection) {
            if (endorsementSection[key]?.field_type === 'datetime' && values[key]) {
              payload.endorsement = { ...payload.endorsement, [key]: moment(values[key]).format('YYYY-MM-DD HH:mm:ss') }
            } else if (endorsementSection[key]?.field_type === 'date' && values[key]) {
              payload.endorsement = { ...payload.endorsement, [key]: moment(values[key]).format('YYYY-MM-DD') }
            } else if (endorsementSection[key]?.field_type === 'year' && values[key]) {
              payload.endorsement = { ...payload.endorsement, [key]: moment(values[key]).format('YYYY') }
            } else {
              payload.endorsement = { ...payload.endorsement, [key]: values[key] }
            }
          }
        }
        const payloadData = {
          internalId: policyId,
          body: payload
        }
        this.props.editPolicyDetails(payloadData)
      }
    })
  }

  render () {
    const {
      policyAttributeData,
      policyAttributeDataLoading,
      policyAttributeDataError,
      policyDetail,
      cancelButton,
      form
    } = this.props
    // const endorsementSection = _.get(policyAttributeData, 'endorsement', {})
    const { getFieldDecorator } = form
    const requestSection = policyAttributeData?.request ?? {}
    const endorsementSection = policyAttributeData?.endorsement ?? {}
    const policyDetailRequest = policyDetail?.Request ?? {}
    const endorsementSetailRequest = policyDetail?.endorsement ?? {}
    const paymentsData = policyDetail?.Payments ?? []

    return (
      <Spin spinning={policyAttributeDataLoading && !policyAttributeDataError}>
        <Form hideRequiredMark>
          <Row>
            <Col>
              <FormStyleWrapper>
                {
                  Object.keys(requestSection)?.length > 0 &&
                  Object.keys(requestSection).map((item, index) => {
                    if (requestSection[item]) {
                      return getFormItems.call(this, {
                        fieldName: item,
                        type: requestSection[item],
                        label: capitalizeFirstLetter(item),
                        initialValue: policyDetailRequest,
                        required: true,
                        idx: index,
                        key: index
                      })
                    }
                    return null
                  })
                }
              </FormStyleWrapper>
            </Col>
            {Object.keys(endorsementSection).length > 0 && policyDetail.EndorsementStatus === 'SUCCESS' &&
              <Col>

                <h3 className='policy-title'>Endorsement Details</h3>
                <FormStyleWrapper>
                  {
                  Object.keys(endorsementSection)?.length > 0 &&
                  Object.keys(endorsementSection).map((item, index) => {
                    if (endorsementSection[item]) {
                      return getFormItems.call(this, {
                        fieldName: item,
                        type: endorsementSection[item],
                        label: capitalizeFirstLetter(item),
                        initialValue: endorsementSetailRequest,
                        required: true,
                        idx: index,
                        key: index
                      })
                    }
                    return null
                  })
                }
                </FormStyleWrapper>
              </Col>}
            <Col>
              <h3 className='policy-title'>Additional Details</h3>
              <Row type='flex' justify='space-around'>
                {
                  paymentsData.length > 0 &&
                  paymentsData.map((item, index) => {
                    return (
                      <React.Fragment key={index}>
                        <Col>
                          <Form.Item label='Payment Premium'>
                            {
                              getFieldDecorator('policy_premium', {
                                rules: [
                                  { required: true }
                                ],
                                initialValue: item.Amount
                              })(<InputNumber />)
                            }
                          </Form.Item>
                        </Col>
                        <Col>
                          <Form.Item label='CoverageStartDate'>
                            {
                              getFieldDecorator('coverage_start', {
                                rules: [
                                  { type: 'object', required: true }
                                ],
                                initialValue: moment(item.CoverageStartDate, 'YYYY-MM-DD HH:mm:ss')
                              })(<DatePicker
                                format='DD-MM-YYYY HH:mm:ss'
                                showTime={{ format: 'DD-MM-YYYY HH:mm:ss' }}
                                 />)
                            }
                          </Form.Item>
                        </Col>
                        <Col>
                          <Form.Item label='CoverageEndDate'>
                            {
                              getFieldDecorator('coverage_end', {
                                rules: [
                                  { type: 'object', required: true }
                                ],
                                initialValue: moment(item.CoverageEndDate, 'YYYY-MM-DD HH:mm:ss')
                              })(
                                <DatePicker
                                  format='DD-MM-YYYY HH:mm:ss'
                                  showTime={{ format: 'DD-MM-YYYY HH:mm:ss' }}
                                />)
                            }
                          </Form.Item>
                        </Col>
                      </React.Fragment>
                    )
                  })
                }
              </Row>
            </Col>
            <Col>
              <Form.Item label='Remarks'>
                {
                  getFieldDecorator('remarks', {
                    rules: [
                      {
                        type: 'string', required: true
                      }
                    ]

                  })(
                    <TextArea rows={3} />
                  )
                }
              </Form.Item>
            </Col>
            <Col>
              <Form.Item>
                {
                  getFieldDecorator('enqueue_flag', {
                    valuePropName: 'checked',
                    initialValue: false
                  })(<Checkbox>Re-generate certificate and re-send policy email</Checkbox>)
                }
              </Form.Item>
            </Col>
            <Button type='primary' className='btn-claim' onClick={cancelButton}> Cancel </Button>
            <Popconfirm
              title='Are you Sure you Want To Edit Policy Details !!'
              okText='Yes'
              cancelText='No'
              onConfirm={this.handleSubmit}
            >
              <Button type='primary' htmlType='submit'> Submit </Button>
            </Popconfirm>
          </Row>
        </Form>
      </Spin>
    )
  }
}
const WrapperFormData = Form.create()(PolicyEditForm)
export default connect(state => ({
  dataProfile: state.Auth.profile,
  submitEditPolicyData: state.Error.EDIT_POLICY_DATA,
  editPolicyDataMessage: state.Insurance.editPolicyDataMessage,
  editPolicyData: state.Insurance.editPolicyData,
  policyDetail: state.Insurance.policyDetail,
  policyEditAttributeDataMessage: state.Insurance.policyEditAttributeDataMessage,
  policyAttributeData: state.Insurance.policyEditAttributeData,
  policyAttributeDataLoading: state.Loading.GET_POLICY_EDIT_ATTRIBUTES,
  policyAttributeDataError: state.Error.GET_POLICY_EDIT_ATTRIBUTES
}), {
  editPolicyDetails,
  resetReduxState
})(WrapperFormData)
