import React from 'react'
import { Table } from 'antd'
import moment from 'moment'

const PolicyPaymentTable = ({ tableData }) => {
  const policyPaymentData = tableData
  const columnsPayment = [
    {
      title: 'Id',
      dataIndex: 'ID',
      key: 'ID'
    }, {
      title: 'Application No',
      dataIndex: 'ApplicationNo',
      key: 'ApplicationNo'
    }, {
      title: 'Amount',
      dataIndex: 'Amount',
      key: 'Amount'
    }, {
      title: 'Txn Ref',
      dataIndex: 'TxnRef',
      key: 'TxnRef'
    }, {
      title: 'Txn Date',
      dataIndex: 'TxnDate',
      key: 'TxnDate'
    }, {
      title: 'Coverage Start Date',
      dataIndex: 'CoverageStartDate',
      key: 'CoverageStartDate'
    }, {
      title: 'Coverage End Date',
      dataIndex: 'CoverageEndDate',
      key: 'CoverageEndDate'
    }
  ]
  const dataPayment = policyPaymentData.map((val, index) => {
    return {
      key: index,
      ID: val.ID,
      ApplicationNo: val.ApplicationNo,
      Amount: val.Amount,
      TxnRef: val.TxnRef,
      TxnDate: moment.utc(val.TxnDate).format('YYYY-MM-DD HH:mm:ss'),
      CoverageStartDate: moment.utc(val.CoverageStartDate).format('DD-MM-YYYY HH:mm:ss'),
      CoverageEndDate: moment.utc(val.CoverageEndDate).format('DD-MM-YYYY HH:mm:ss')
    }
  })
  return (
    <Table
      pagination={{ pageSize: 25 }}
      columns={columnsPayment}
      dataSource={dataPayment}
      scroll={{ x: true }}
    />
  )
}

export default PolicyPaymentTable
