import React from 'react'
import { Row, Col, Table } from 'antd'
import { validUrl } from '../../../../../helpers/utility'
import EndorsementWrapper from './index.style'

const EndorsementTable = ({ dataSource, methods, columns }) => {
  const { renderData } = methods
  const dataEndorsement = dataSource
  const columnsEndorsement = columns
  return (
    <EndorsementWrapper>
      <Row>
        <h3 className='policy-title'>Endorsement Details</h3>
        <Col span={24}>
          {
            dataEndorsement.map(item => {
              // if (item.hasOwnProperty('nonArray')) {
              if (Object.prototype.hasOwnProperty.call(item, 'nonArray')) {
                item = item.nonArray
                return (
                  <>
                    <Row className='row-style'>
                      <Col xs={12}>
                        <strong>
                          {item[0].key}
                        </strong>
                      </Col>
                      <Col xs={12}>
                        {renderData(item[0].value)}
                      </Col>
                    </Row>
                    <hr className='line-break-style' />
                  </>
                )
              }
              return null
            })
          }
          {
            dataEndorsement.map(item => {
              if (Object.prototype.hasOwnProperty.call(item, 'arrayData')) {
                const tableData = item.arrayData
                if (Array.isArray(tableData)) {
                  tableData.forEach(item => {
                    if (typeof item === 'object') {
                      Object.values(item).forEach((images, index) => {
                        const href = (images && validUrl(images)) ? <span key={index} className='anchor' onClick={() => { this.openEndorsementImage(images) }}>{images}</span> : images
                        Object.keys(item).forEach(key => {
                          if (item[key] === images) {
                            item[key] = href
                          }
                        })
                      })
                    }
                  })
                }
                return (
                  <Table
                    pagination={{ pageSize: 100 }}
                    showHeader
                    columns={columnsEndorsement}
                    dataSource={tableData}
                  />
                )
              }
              return null
            })
          }
        </Col>
      </Row>
    </EndorsementWrapper>
  )
}

export default EndorsementTable
