import React from 'react'
import { connect } from 'react-redux'
import {
  Row,
  Col,
  Input,
  Tag,
  Modal,
  notification,
  Form,
  Spin,
  Button
} from 'antd'
import moment from 'moment'
import { get } from 'lodash'
import insuranceAction from '../../../redux/policy/actions'
import errorAction from '../../../redux/error/actions'
import loadingAction from '../../../redux/loading/actions'
import policyStatusColor from './policyStateStatus'
import PermissionChecker from '../../../components/permissionChecker'
import pencilIcon from '../../../image/pencil-icon.png'
import claimActions from '../../redux/claims/actions'
import ChangeNumber from '../Customer/PolicyChangeNumber.js'
import { ChangeNumberStyle } from '../Customer/changeNumber.style'

const { updatePolicyNumber } = insuranceAction
const handleViewDocument = documentUrl => {
  window.open(documentUrl, '_blank')
}
const { sendOtp, changeUserPhone, createApprovalList, resetReduxStateClaim } = claimActions
const { resetErrorRedux } = errorAction
const { resetLoadingRedux } = loadingAction

const DYNAMIC_ENDORSE_PACKAGES = ['aus-safetrip-premium-2w', 'aus-safetrip-premium-4w', 'aus-safetrip-premium-2w-2026', 'aus-safetrip-premium-4w-2026']

class PolicyDetailsTable extends React.Component {
  state = {
    policyNumber: '',
    policyNumberEditable: true,
    policyDetail: {},
    openMobileChangePopup: false,
    updateMobileNumberStatus: undefined,
    verifyData: {},
    dynamicEndorsePolling: false,
    dynamicEndorsePollCount: 0,
    dynamicEndorseTriggered: false,
  }
  componentDidMount() {
    this.props.resetErrorRedux(['SEND_OTP', 'CHANGE_USER_PHONE'])
    this.props.resetLoadingRedux(['SEND_OTP', 'CHANGE_USER_PHONE'])
  }

  componentWillUnmount() {
    if (this._pollInterval) clearInterval(this._pollInterval)
  }
  UNSAFE_componentWillReceiveProps(nextProps) {
    const { policyDetail, createApprovalMessage } = nextProps
    this.setState({ policyNumber: policyDetail.InsurancePolicyNo, policyDetail })

    if (nextProps.sendOtpStatus && nextProps.sendOtpLoading === false) {
      notification[nextProps.sendOtpError ? 'error' : 'success']({ message: nextProps.sendOtpStatus })
      // this.setState({ newNumberEntered: true })
    }
    if (nextProps.sendOtpError === false && nextProps.sendOtpLoading === false) {
      this.setState({ newNumberEntered: true })
      this.props.resetErrorRedux(['SEND_OTP'])
      this.props.resetLoadingRedux(['SEND_OTP'])
    }

    if (nextProps.changeNumberStatus && nextProps.changeUserPhoneLoading === false) {
      notification[nextProps.changeUserPhoneError ? 'error' : 'success']({ message: nextProps.changeNumberStatus })
    }
    if (nextProps.changeUserPhoneError === false && nextProps.changeUserPhoneLoading === false) {
      this.setState({ openMobileChangePopup: false, newNumberEntered: false })
      // this.props.getClaimByCustomer(this.props.match.params.user_id)
      this.props.getPolicyDetails()
      this.props.resetErrorRedux(['CHANGE_USER_PHONE'])
      this.props.resetLoadingRedux(['CHANGE_USER_PHONE'])
    }

    if (createApprovalMessage !== '') {
      if (createApprovalMessage === 'success') {
        notification.success({
          message: 'OTP Verified',
          description: "Added in Approval Task"
        })
        this.setState({
          openMobileChangePopup: false,
          newNumberEntered: false
        })
      } else {
        notification.error({
          message:
            createApprovalMessage || 'Failed to Verify OTP'
        })
      }
      this.props.resetReduxStateClaim(['createApprovalMessage'])
      this.props.resetLoadingRedux(['CREATE_APPROVAL_LIST'])
    }

    if (this.state.dynamicEndorseTriggered && nextProps.dynamicEndorseLoading === false) {
      this.setState({ dynamicEndorseTriggered: false })
      if (nextProps.dynamicEndorseError) {
        notification.error({ message: nextProps.dynamicEndorseMessage || 'Failed to trigger certificate generation' })
      } else {
        this.startDynamicEndorsePolling()
      }
    }

    if (this.state.dynamicEndorsePolling && nextProps.policyDetail.DocumentURL && nextProps.policyDetail.DocumentURL !== 'NA') {
      this.stopDynamicEndorsePolling()
      notification.success({ message: 'Certificate generated successfully' })
    }
  }

  startDynamicEndorsePolling = () => {
    const MAX_POLLS = 6
    this.setState({ dynamicEndorsePolling: true, dynamicEndorsePollCount: 0 })
    this._pollInterval = setInterval(() => {
      const { dynamicEndorsePollCount } = this.state
      if (dynamicEndorsePollCount >= MAX_POLLS) {
        this.stopDynamicEndorsePolling()
        notification.warning({ message: 'Certificate is still being processed, please refresh the page in a moment' })
        return
      }
      this.props.getPolicyDetails()
      this.setState(prev => ({ dynamicEndorsePollCount: prev.dynamicEndorsePollCount + 1 }))
    }, 5000)
  }

  stopDynamicEndorsePolling = () => {
    if (this._pollInterval) {
      clearInterval(this._pollInterval)
      this._pollInterval = null
    }
    this.setState({ dynamicEndorsePolling: false, dynamicEndorsePollCount: 0 })
  }

  handleDynamicEndorse = () => {
    const { policyDetail } = this.state
    this.setState({ dynamicEndorseTriggered: true })
    this.props.dynamicEndorse({ internalId: policyDetail.InternalID })
  }

  handleOk = e => {
    this.setState({ openMobileChangePopup: false })
  };

  handleCancel = e => {
    this.setState({ openMobileChangePopup: false })
  };
  handleChangePolicyNumberInput = val => {
    this.setState({ policyNumber: val.target.value })
  }
  handleInsuranceEditable = () => {
    this.setState({
      policyNumberEditable: !this.state.policyNumberEditable
    })
  }
  handleChangePhoneNumber = () => {
    this.setState({ openMobileChangePopup: true, newNumberEntered: false })
  }
  handleUpdatePolicyNumber = () => {
    const { params } = this.props.generalProps.match
    // eslint-disable-line
    const format = /[!@#$%^&*()_+=[\]{};':"\\|,.<>/?]/
    if (this.state.policyNumber === '' || this.state.policyNumber === '-') {
      alert('Policy number cannot be empty')
      return
    } else if (format.test(this.state.policyNumber)) {
      alert('Policy number cannot contain special characters')
      return
    }
    this.setState({ policyNumberEditable: true })
    this.props.updatePolicyNumber({ id: params.policy_id, policy_no: this.state.policyNumber })
  }

  handlecustomerDetailPage(id) {
    const { push } = this.props.generalProps.history
    push({ pathname: `/customer/${id}` })
  }

  handleApplicationDetailPage(uniqueKey) {
    const { push } = this.props.generalProps.history
    push({ pathname: `/agent/application/${uniqueKey}` })
  }

  renderReferenceId(uniqueKey, orderNumber) {
    if (!orderNumber) {
      return <p>{uniqueKey}</p>
    }
    return (
      <a
        href={`/agent/application/${orderNumber}`}
        onClick={(e) => {
          e.preventDefault()
          this.handleApplicationDetailPage(orderNumber)
        }}
      >{uniqueKey}</a>
    )
  }

  handleOkNumberChange = (values) => {
    const { policyDetail } = this.state
    if (values) this.setState({ values })
    let data = {
      type: 'phone',
      partner: policyDetail.Partner,
      phone: values
        ? `${values.prefix}-${values.new_number}`
        : `${this.state.values.prefix}-${this.state.values.new_number}`
    }
    this.props.sendOtp(data)
    this.setState({ openMobileChangePopup: true })
  }

  handleCancelNumberChange = () => {
    this.setState({ openMobileChangePopup: false, newNumberEntered: false })
  }

  onSubmitNumberChange = (value) => {
    const { otpData } = this.props
    const { values, policyDetail } = this.state

    let data = {
      operation_id: otpData.operation_id,
      new_phone: `${values.prefix}-${values.new_number}`,
      name: policyDetail.Name,
      email: policyDetail.Email,
      partner: policyDetail.Partner,
      internal_ids: [policyDetail.InternalID],
      otp: value.otp
    }

    data.old_phone = policyDetail?.MobileNo || ''

    const verifyData = {
      identifier: policyDetail?.ApplicationNo || otpData?.operation_id,
      ticket_id: values?.zoho_id,
      otp: value?.otp,
      operation_id: otpData?.operation_id,
      new_phone: `${values.prefix}-${values.new_number}`,
      name: policyDetail.Name,
      email: policyDetail.Email,
      response: data,
      action: 'change-user-phone'
    }

    this.setState({ verifyData: verifyData })
    this.props.createApprovalList(verifyData)
  }

  render() {
    const { changeUserPhoneLoading, sendOtpLoading, createApprovalLoading } = this.props
    const { policyNumberEditable, policyNumber, policyDetail, openMobileChangePopup, newNumberEntered } = this.state
    let permissions = this.props.permissionsList
    let policyStartDate = ''
    if (policyDetail.PolicyStart !== undefined && policyDetail.PolicyStart.Valid === true) {
      policyStartDate = policyDetail.PolicyStart.Time
    }
    let color = policyStatusColor(policyDetail.PolicyState)
    const orderNumber = get(policyDetail, 'Request.order_number')

    return (<div>
      <Modal
        title='Change Phone Number'
        visible={openMobileChangePopup}
        onCancel={this.handleCancel}
        footer={null}
      // closable={false}
      >
        <Spin spinning={!!changeUserPhoneLoading || !!sendOtpLoading || !!createApprovalLoading}>
          <ChangeNumberStyle>
            <ChangeNumber
              newNumberEntered={newNumberEntered}
              onCancel={() => this.handleCancelNumberChange()}
              onSave={(values) => this.handleOkNumberChange(values)}
              onResend={() => this.handleOkNumberChange()}
              onSubmit={(value) => this.onSubmitNumberChange(value)}
              oldPhoneNumber={policyDetail.MobileNo}
            />
          </ChangeNumberStyle>
        </Spin>
      </Modal>
      <Row style={{
        margin: '20px 0 20px 0'
      }}>
        <Col span={3}>
          <strong>Application status:</strong>
        </Col>
        <Col span={21}>
          <Tag color={color}>{
            Object.values(policyDetail).length > 0
              ? policyDetail.PolicyState
              : '-'
          }</Tag>
        </Col>
      </Row>
      <Row gutter={32} className='detais-data-row'>
        <Col span={6}>
          <span>Application Number</span>
          <p>{policyDetail.ApplicationNo || '-'}</p>
        </Col>
        <Col span={6}>
          <span>Product Name</span>
          <p>{policyDetail.ProductDisplayName || '-'}</p>
        </Col>
        <Col span={6}>
          <span>Policy Number</span>
          {
            (policyDetail.InsurancePolicyNo === '' || policyDetail.InsurancePolicyNo === '-')
              ? (<PermissionChecker permissionSetter='ops.update_policy_number' permissionGetter={permissions}>
                <Input disabled={policyNumberEditable} addonAfter={(
                  policyNumberEditable === false)
                  ? <i className='fa fa-save' onClick={this.handleUpdatePolicyNumber} style={{
                    cursor: 'pointer'
                  }} />
                  : <i className='fa fa-edit' onClick={this.handleInsuranceEditable} style={{
                    cursor: 'pointer'
                  }} />} onChange={this.handleChangePolicyNumberInput} value={policyNumber} />
              </PermissionChecker>)
              : <p>{policyDetail.InsurancePolicyNo}</p>
          }
        </Col>
        <Col span={6}>
          <span>Document URL</span>
          <p>
            {(() => {
              const isGojekPA = policyDetail.Partner === 'gojek' &&
                policyDetail.ProductKey === 'personal-accident' &&
                DYNAMIC_ENDORSE_PACKAGES.includes(policyDetail.PackageCodeSlug)
              if (isGojekPA) {
                const { dynamicEndorsePolling } = this.state
                const isLoading = !!this.props.dynamicEndorseLoading || dynamicEndorsePolling
                return (
                  policyDetail.DocumentURL && policyDetail.DocumentURL !== 'NA'
                    ? <span className='anchor' onClick={() => handleViewDocument(policyDetail.DocumentURL)}>View File</span>
                    : <Button
                        onClick={this.handleDynamicEndorse}
                        loading={isLoading}
                        className='btn-generate-policy'
                      >
                        {isLoading ? 'Generating...' : 'Generate Certificate'}
                      </Button>
                )
              }
              return policyDetail.DocumentURL && policyDetail.DocumentURL !== 'NA'
                ? <span className='anchor' onClick={() => handleViewDocument(policyDetail.DocumentURL)}>View File</span>
                : '-'
            })()}
          </p>
        </Col>
      </Row>
      <Row gutter={32} className='detais-data-row'>
        <Col span={6}>
          <span>Identity Number</span>
          <p>{policyDetail.IdentityNo || '-'}</p>
        </Col>
        <Col span={6}>
          <span>Email</span>
          <p className='wordBreak'>{policyDetail.Email || '-'}</p>
        </Col>
        <Col span={6}>
          <span>Mobile Number</span>
          <p>{policyDetail.MobileNo || '-'}
            <PermissionChecker permissionSetter='ops.change_user_number' permissionGetter={permissions}>
              <img src={pencilIcon} className='btn-icon-pencil' onClick={this.handleChangePhoneNumber} alt='' />
            </PermissionChecker>
          </p>
        </Col>
        <Col span={6}>
          <span>Policy Start Date</span>
          <p>{
            policyStartDate !== ''
              ? moment.utc(policyStartDate).format('DD MMMM YYYY')
              : '-'
          }</p>
        </Col>
      </Row>
      <Row gutter={32} className='detais-data-row'>
        <Col span={6}>
          <span>Created At</span>
          <p>{
            policyDetail.CreatedAt
              ? moment(policyDetail.CreatedAt).format('DD MMMM YYYY')
              : '-'
          }</p>
        </Col>
        <Col span={6}>
          <span>Updated At</span>
          <p>{
            policyDetail.UpdatedAt
              ? moment(policyDetail.UpdatedAt).format('DD MMMM YYYY')
              : '-'
          }</p>
        </Col>
        <Col span={6}>
          <span>Name</span>
          {
            !!policyDetail.Name && !!policyDetail.Userid
              ? <span className='anchor' onClick={() => this.handlecustomerDetailPage(policyDetail.Userid)} style={{
                cursor: 'pointer',
                textDecoration: 'underline'
              }}>
                {policyDetail.Name}
              </span>
              : <span className='anchor'>{policyDetail.Name || '-'}</span>
          }
        </Col>
        <Col span={6}>
          <span>Coupon Code</span>
          <p>{policyDetail.CouponCode || '-'}</p>
        </Col>
      </Row>
      <Row gutter={32} className='detais-data-row'>
        <Col span={6}>
          <span>Insured</span>
          {
            !!policyDetail.Insured &&
            <p>{policyDetail.Insured.toString() || '-'}</p>
          }
        </Col>
        {
          !!policyDetail.UniqueKey &&
          <Col span={6}>
            <span>Reference ID</span>
            {this.renderReferenceId(policyDetail.UniqueKey, orderNumber)}
          </Col>
        }
      </Row>
    </div>)
  }
}
const WrappedPolicyDetail = Form.create()(PolicyDetailsTable)
export default connect(state => ({
  policy: state.Insurance,

  sendOtpLoading: state.Loading.SEND_OTP,
  sendOtpError: state.Error.SEND_OTP,
  sendOtpStatus: state.Claims.sendOtpStatus,
  otpData: state.Claims.otpData,

  changeUserPhoneLoading: state.Loading.CHANGE_USER_PHONE,
  changeUserPhoneError: state.Error.CHANGE_USER_PHONE,
  changeNumberStatus: state.Claims.changeNumberStatus,
  createApprovalMessage: state.Claims.createApprovalMessage,
  createApprovalLoading: state.Loading.CREATE_APPROVAL_LIST,
  dynamicEndorseLoading: state.Loading.DYNAMIC_ENDORSE,
  dynamicEndorseError: state.Error.DYNAMIC_ENDORSE,
  dynamicEndorseMessage: state.Insurance.dynamicEndorseMessage,
}), {
  updatePolicyNumber,
  sendOtp,
  changeUserPhone,
  resetErrorRedux,
  resetLoadingRedux,
  createApprovalList,
  resetReduxStateClaim,
  dynamicEndorse: insuranceAction.dynamicEndorse,
})(WrappedPolicyDetail)
