  UNSAFE_componentWillReceiveProps (nextProps) {
    const { permissions } = nextProps.dataProfile
    const {
      policyPaymentData,
      statusGetPaymentDetails,
      updatePolicyNoStatus,
      retriggerNotificationError,
      retriggerNotificationStatus,
      data,
      getClaimListsStatus,
      statusCancelPolicy,
      statusTerminatePolicy,
      notificationsData,
      getNotficationsListStatus,
      internalCancellationMessage,
      policyDetail,
      getPolicyDetailsMessage,
      webhookLogDataMessage,
      webhookLogData,
      wehbookRetryMessage,
      reactivatePolciyMessage,
      reactivatePolciyData
    } = nextProps
    if (getPolicyDetailsMessage === 'success') {
      this.setState({ policyDetails: policyDetail }, () => {
        this.setPoliciesTables()
        this.setCancellationandReactivateTable()
        if (_.size(policyDetail) > 0) {
          this.props.getWebhookLogs({
            query: {
              partner: _.get(policyDetail, 'Partner', ''),
              product: _.get(policyDetail, 'ProductKey', ''),
              internal_id: _.get(policyDetail, 'InternalID', '')
            }
          })
        }
      })
      this.props.resetInsuranceRedux(['getPolicyDetailsMessage'])
    }
    if (getPolicyDetailsMessage && getPolicyDetailsMessage !== 'success') {
      notification.error({
        message: 'Policy Detail unable to load'
      })
      this.props.resetInsuranceRedux(['getPolicyDetailsMessage'])
    }
    if (Array.isArray(permissions)) { this.setState({ permissions }) }
    if (getNotficationsListStatus !== '') {
      this.setState({ notificationsData, getNotficationsListStatus })
      this.props.resetInsuranceRedux(['getNotficationsListStatus'])
    }
    if (getClaimListsStatus !== '') {
      this.setState({ getClaimListsStatus, claimData: data.data, claimMetaData: data.meta_data })
      this.props.resetInsuranceRedux(['getClaimListsStatus'])
    }
    if (getClaimListsStatus === statusCodes.SERVER_ERROR) {
      this.setState({ getClaimListsStatus, claimData: [], claimMetaData: {} })
    }
    if (updatePolicyNoStatus !== '') {
      this.setState({ updatePolicyNoStatus: updatePolicyNoStatus })
      this.props.resetInsuranceRedux(['updatePolicyNoStatus'])
    }
    if (statusCancelPolicy) {
      if (statusCancelPolicy === 'success') {
        this.getPolicyDetails()
        this.props.resetReduxState(['statusCancelPolicy'])
      }
      this.setState({ statusCancelPolicy, cancellationLoader: false, isPolicyCancellationModal: false })
    }
    if (statusTerminatePolicy !== undefined) {
      this.setState({ statusTerminatePolicy, terminationLoader: false })
    }
    if (internalCancellationMessage !== undefined) {
      this.setState({ internalCancellationMessage })
    }
    if (statusGetPaymentDetails !== undefined) {
      this.setState({ statusGetPaymentDetails })
    }
    if (policyPaymentData !== undefined) {
      this.setState({ policyPaymentData })
    }
    if (reactivatePolciyMessage) {
      if (reactivatePolciyMessage === 'success') {
        this.setState({
          isPolicyReactivateModal: false
        })
        this.getPolicyDetails()
        notification.success({
          message: _.get(reactivatePolciyData, 'data.message', 'Policy reactivating successfully')
        })
      } else {
        notification.error({
          message: reactivatePolciyMessage
        })
      }
      this.props.resetInsuranceRedux(['reactivatePolciyMessage'])
    }
    // if ((statusTerminatePolicy === 'success') || (statusCancelPolicy === 'success') || (internalCancellationMessage === 'success')) {
    //   // this function called to update policy details
    //   this.initiatState()
    //   this.props.resetInsuranceRedux(['statusTerminatePolicy', 'statusCancelPolicy', 'internalCancellationMessage'])
    // }
    // if (retriggerNotificationStatus !== '') {
    //   notification['success']({ message: retriggerNotificationStatus, description: '' })
    //   this.props.resetNotificationsRedux(['retriggerNotificationStatus'])
    // }
    if (retriggerNotificationStatus !== '') {
      notification[retriggerNotificationError ? 'error' : 'success']({ message: retriggerNotificationStatus })
      this.setState({ showResendForm: retriggerNotificationError })
      this.props.resetNotificationsRedux(['retriggerNotificationStatus'])
      this.props.getNotificationList({
        query: {
          reference_id: _.get(this.props, 'match.params.policy_id', ''),
          page: 1,
          per_page: this.state.notificationRowData
        }
      })
    }
    if (webhookLogDataMessage === 'success') {
      this.setState({
        webHookData: webhookLogData
      })
      this.props.resetInsuranceRedux(['webhookLogMessage'])
    }

    if (wehbookRetryMessage) {
      const { error, message, success } = wehbookRetryMessage
      if (error) {
        notification.error({
          message: error
        })
      } else if (success) {
        notification.success({
          message: message
        })
      }

      if (_.size(policyDetail) > 0) {
        this.props.getWebhookLogs({
          query: {
            partner: _.get(policyDetail, 'Partner', ''),
            product: _.get(policyDetail, 'ProductKey', ''),
            internal_id: _.get(policyDetail, 'InternalID', '')
          }
        })
      }

      this.props.resetInsuranceRedux(['wehbookRetryMessage'])
    }
  }

