  onBackPolicy = () => {
    const { history, location } = this.props
    const { state } = location
    if (history) {
      const { action } = history
      if (action === 'POP') {
        history.push('/policy', { state: state ? { ...state.filters } : '' })
      } else {
        history.goBack()
      }
    }
  }

