  handleWebhookTableChange = (pagination) => {
    const { pageSize, current } = pagination
    const { policyDetail } = this.props
    const offset = 5 * (current - 1)
    const finalFilter = {
      page: Number(current),
      limit: Number(pageSize),
      offset: offset
    }
    this.setState({
      webhookPage: current
    }, () => this.props.getWebhookLogs({
      query: {
        partner: _.get(policyDetail, 'Partner', ''),
        product: _.get(policyDetail, 'ProductKey', ''),
        internal_id: _.get(policyDetail, 'InternalID', ''),
        ...finalFilter
      }
    }))
  }

    fetch = (params = {}) => {
      const {
        page: pageParam,
        page_size: pageSizeParam
      } = params
      const page = Number(pageParam) || 1
      const pageSize = Number(pageSizeParam) || 50
      delete params.page
      delete params.page_size
      this.setState({ page_size: pageSize, page, claimsFilter: params, searchTextQuery: params })
      this.props.getClaimLists({
        page,
        page_size: pageSize,
        ...params
      })
    }

  handleClaimListTableChange = (pagination, filters, sorter) => {
    const { history, location } = this.props
    const { searchTextQuery, policyDetails } = this.state
    const { pageSize, current } = pagination
    const filterObj = {}
    Object.keys(filters).map((key, index) => {
      let value = filters[key] || []
      value = Array.isArray(value)
        ? value[0]
        : value
      if (value) { filterObj[key] = value }
      return filterObj
    })
    const querySearch = QueryString.parse(location.search)
    const finalFilter = {
      ...searchTextQuery,
      ...filterObj,
      ...querySearch,
      application_no: _.get(policyDetails, 'ApplicationNo', ''),
      page: current,
      page_size: pageSize
    }
    const searchQuery = QuerySearchBuilder(finalFilter)
    history.push({ pathname: location.pathname, search: searchQuery })
    this.setState({
      policy_number: false,
      claim_no: false,
      application_no: false,
      onSearchQuery: finalFilter,
      searchTextQuery: finalFilter,
      filteredInfo: {
        ...filterObj
      },
      page: current,
      page_size: pageSize
    }, () => this.fetch(finalFilter))
  }

  setPoliciesTables = () => {
    const { policyDetails } = this.state
    const policyRequest = _.get(policyDetails, 'Request', {})
    if (!_.isEmpty(policyRequest)) {
      const notParsingKeys = ['userid', 'nationality']

      const request = policyRequest
      // delete request['userid']
      // delete request['city']
      // delete request['nationality']
      // delete request['province']
      // delete request['Insured']
      let count = 0
      const insertedObjectValue = []
      const columnPolicyDetails = []

      try {
        const extraDataStr = _.get(policyDetails, 'ExtraData', '')
        if (extraDataStr) {
          const extraData = JSON.parse(extraDataStr)
          if (extraData.premium_breakdown && typeof extraData.premium_breakdown === 'object') {
            insertedObjectValue.push({ key: 'premium_breakdown', value: extraData.premium_breakdown })
          }
        }
      } catch (e) { /* ExtraData is not valid JSON */ }

      for (const key in request) {
        if (!notParsingKeys.includes(key)) {
          switch (typeof request[key]) {
            case 'string':
            case 'number':
            case 'boolean':
              columnPolicyDetails.push({
                key: count,
                name: <strong>{capitalizeFirstLetter(key)}</strong>,
                value: request[key] || request[key] === 0 ? request[key].toString() : '-'
              })
              count++
              // delete request[key]
              break
            case 'object':
              /* eslint-disable */
              if (Array.isArray(request[key])) {
                if (key === 'insured_names') {
                  columnPolicyDetails.push({
                    key: count,
                    name: <strong>{capitalizeFirstLetter(key)}</strong>,
                    value: request[key] ? request[key].toString() : '-'
                  })
                } else {
                  let storingArrayData = []
                  request[key].forEach(item => {
                    if (typeof item === 'string') {
                      columnPolicyDetails.push({
                        key: count,
                        name: <strong>{capitalizeFirstLetter(key)}</strong>,
                        value: request[key] ? request[key].toString() : '-'
                      })
                      count++
                    } else {
                      storingArrayData.push(item)
                    }
                  })
                  insertedObjectValue.push({ key, value: storingArrayData })
                }
              } else {
                let insertedObject = {
                  'key': key,
                  'value': request[key] ? request[key] : []
                }
                insertedObjectValue.push(insertedObject)
                // delete request[key]
              }
              break
            default: return null
          }
        }
      }
      this.setState({
        ...(insertedObjectValue.length > 0 ? { dynamicTables: insertedObjectValue } : {}),
        ...(columnPolicyDetails.length > 0 ? { columnPolicyDetailsReq: columnPolicyDetails } : {})
      })
    }
  }

  setCancellationandReactivateTable = () => {
    const { policyDetails } = this.state
    const request = _.get(policyDetails, 'closure', {})
    const cancelAndReactivateDetails = []

    const cancelDetailsKey = [
      {
        "title": "Cancelled By",
        "key": "CancelledBy",
      },
      {
        "title": "Cancelled At",
        "key": "ExecutionDate",
        render: (value) => value ? moment.utc(value).format('YYYY-MM-DD  HH:mm:ss') : null
      },
      {
        "title": "Reason",
        "key": "Reason"
      },
      {
        "title": "Cancellation Document URLs",
        "key": "CancellationDocumentURLs",
        render: (value) => {
          if (value && Array.isArray(value)) {
            return (
              <div class="flex g-8">
                {
                  value.map((item) => (
                    <Button
                      type='primary'
                      key={item}
                    >
                      <a href={item} target='_blank'>View</a>
                    </Button>
                  ))
                }
              </div>
            )
          }
          if (value) {
            return (
              <Button
                type='primary'
              >
                <a href={value} target='_blank'>View</a>
              </Button>

            )
          }
        }
      },
      {
        "title": "Reactivated By",
        "key": "ReactivatedBy"
      },
      {
        "title": "Reactivated At",
        "key": "ReactivatedAt",
        render: (value) => value ? moment.utc(value).format('YYYY-MM-DD  HH:mm:ss') : null
      },
      {
        "title": "Reactivation Reason",
        "key": "ReactivationReason"
      },
      {
        "title": "Reactivation Document URLs",
        "key": "ReactivationDocumentURLs",
                 render: (value) => {
          if (value && Array.isArray(value)) {
            return (
              <div class="flex g-8">
                {
                  value.map((item) => (
                    <Button
                      type='primary'
                      key={item}
                    >
                      <a href={item} target='_blank'>View</a>
                    </Button>
                  ))
                }
              </div>
            )
          }
          if (value) {
            return (
              <Button
                type='primary'
              >
                <a href={value} target='_blank'>View</a>
              </Button>

            )
          }
        }
      }
    ]
    if (!_.isEmpty(request)) {
      for (const { title, key, render } of cancelDetailsKey) {
        let value = request[key]
        if (render) {
          value = render(value)
        }
        cancelAndReactivateDetails.push({
          key,
          name: <strong>{title}</strong>,
          value: value
        })
      }
    }

    this.setState({
      cancelAndReactivateDetails
    })
  }

