import React from 'react'
import { capitalizeFirstLetter, getTableKeys } from '../../../../../helpers/utility'
import { Row, Col, Table } from 'antd'
import DebitorComponent from '../DebitorComponent'
import StaticColumns from './tableColumnMappers'
import _ from 'lodash'
import LayoutContentStyle from '../../../../../components/utility/layoutContent'

const staticTableRender = (tableName, columns, dataSource) => {
  return (
    <LayoutContentStyle className='details-info-container policy-detail-card'>
      <Row>
        <h3 className='policy-title'>{capitalizeFirstLetter(tableName)}</h3>
        <Col span={24}>
          <Table
            pagination={{ pageSize: 100 }}
            columns={columns}
            dataSource={dataSource}
            scroll={{ x: true }}
          />
        </Col>
      </Row>
    </LayoutContentStyle>
  )
}
const genericColumns = (data) => {
  let columns = []
  if (!_.isEmpty(data)) {
    const arrayCheck = Array.isArray(data)
    if (arrayCheck === false) {
      data = [data]
    }
    data.map((val, index) => {
      columns = getTableKeys(val)
      return columns
    })
  }

  return columns
}
const genericData = (data) => {
  const dataSource = []
  if (!_.isEmpty(data)) {
    const arrayCheck = Array.isArray(data)
    if (arrayCheck === false) {
      data = [data]
    }
    data.map((val, index) => {
      dataSource[index] = val
      return dataSource
    })
  }
  return dataSource
}

const dataLengthCheck = (dataSource) => (dataSource.length > 0)

const GenericTableComponent = ({ data, methods }) => {
  /* eslint-disable */
  return data.map((item, index) => {
    switch (item.key) {
      case 'train_information': {
        const dataMembers = item['value'].map((val, index) => {
          return {
            key: index,
            departure_date: val.departure_date,
            destination_station: val.destination_station,
            pnr: val.pnr,
            source_station: val.source_station,
            train_id: val.train_id
          }
        })
        if (dataLengthCheck(item['value'])) return staticTableRender(item.key, StaticColumns.columnTrainInformations, dataMembers)
      }
        break
      case 'application_details':
      //case 'Insured':
      //case 'Insured': 
      {
        let dataDetailsInsured = []
        let finalDataInsured = []
        finalDataInsured = Array.isArray(item['value']) ? item['value'] : [item['value']]
        finalDataInsured.length > 0 && finalDataInsured.map((val, index) => {
          dataDetailsInsured = [
            ...dataDetailsInsured, {
              key: index,
              CustName: (val.CustName || val.name) || '-',
              City: (val.City || val.city) || '-',
              Email: (val.Email || val.email) || '-',
              CustAddress: (val.CustAddress || val.address) || '-',
              HandPhone: (val.HandPhone || val.phone_no) || '-',
              InsuredIdNo: (val.InsuredIdNo) || '-',
              Status: (val.Status) || '-',
              IdentityNo: (val.ktp_no) || '-',
              Relationship: (val.relation_ship) || '-',
              Gender: (val.gender || val.Gender) || '-',
              AgeGroup: (val.age_group) || '-',
              dob: ((val.dob || val.date_of_birth) || val.DateOfBirth) || '-'
            }
          ]
          return dataDetailsInsured
        })
        if (dataLengthCheck(item['value'])) return staticTableRender(item.key, StaticColumns.columnsInsured, dataDetailsInsured)
      }
        break
      case 'personal_data_images':
      case 'vehicle_images': {
        const dataMembers = item['value'].map((val, index) => {
          return {
            key: index,
            name: val.name,
            full_size_url: <img src={val.full_size_url} width='auto' alt='' height='100px' />
          }
        })
        if (dataLengthCheck(item['value'])) return staticTableRender(item.key, StaticColumns.vehicleImgCol, dataMembers)
      }
        break
      case 'documents' : {
        const dataMembers = item['value'].map((val, index) => {
          return {
            key: index,
            name: val.name,
            full_size_url: <img src={val.full_size_url} width='auto' alt='' height='100px' />
          }
        })
        if (dataLengthCheck(item['value'])) return staticTableRender(item.key, StaticColumns.documentsColumns, dataMembers)
      }
        break
      case 'member' : {
        const dataMembers = item['value'].map((val, index) => {
          return {
            key: index,
            dob: val.dob,
            gender: val.gender,
            identity_card: val.identity_card,
            identity_number: val.identity_number,
            name: val.name,
            relationship: val.relationship
          }
        })
        if (dataLengthCheck(item['value'])) return staticTableRender(item.key, StaticColumns.member, dataMembers)
      }
        break
      case 'premium_breakdown': {
        const pb = item['value']
        const rows = [
          { key: 'base_premium', name: 'Base Premium', value: `IDR ${(pb.base_premium || 0).toLocaleString('id-ID')}` },
          ...(pb.fees || []).map(fee => ({ key: fee.key, name: fee.label, value: `IDR ${(fee.amount || 0).toLocaleString('id-ID')}` })),
          { key: 'subtotal', name: 'Subtotal', value: `IDR ${(pb.subtotal || 0).toLocaleString('id-ID')}` },
          { key: 'discount_percent', name: 'Discount (%)', value: `${pb.discount_percent || 0}%` },
          { key: 'discount_amount', name: 'Discount Amount', value: `IDR ${(pb.discount_amount || 0).toLocaleString('id-ID')}` },
          { key: 'final_premium', name: 'Final Premium', value: `IDR ${(pb.final_premium || 0).toLocaleString('id-ID')}` }
        ]
        return staticTableRender('Premium Breakdown', [{ title: 'Name', dataIndex: 'name', key: 'name' }, { title: 'Value', dataIndex: 'value', key: 'value' }], rows)
      }
      case 'Debitor' : return (
        <DebitorComponent data={item['value']} arrayFunction={methods.debitorComponentFunction} />
      )
      default :
        return (
          <LayoutContentStyle className='details-info-container policy-detail-card'>
            <Row>
              <h3 className='policy-title'>{ capitalizeFirstLetter(item.key) }</h3>
              <Col span={24}>
                <Table
                  pagination={{ pageSize: 100 }}
                  columns={genericColumns(item.value)}
                  dataSource={genericData(item.value)}
                  scroll={{ x: true }}
                />
              </Col>
            </Row>
          </LayoutContentStyle>
        )
    }
  })
}

export default GenericTableComponent
