import React, { Component } from 'react'
import _ from 'lodash/object'
import { capitalizeFirstLetter } from '../../../../../helpers/utility'
import { Row, Col, Table } from 'antd'
import LayoutContentStyle from '../../../../../components/utility/layoutContent'

class DebitorComponent extends Component {
  state = {
    tableColumns: [],
    debitorDataSource: []
  }

  componentDidMount () {
    const { data } = this.props
    const firstObj = _.get(data, '[0]', {})
    const columnKeys = Object.keys(firstObj)
    const tableColumns = this.mapkeystoTableColumns(columnKeys, firstObj)
    this.setState({
      tableColumns,
      debitorDataSource: data
    })
  }

  mapkeystoTableColumns = (columnKeys, firstObj) => {
    return columnKeys.map(key => {
      if (Array.isArray(firstObj[key])) {
        return {
          title: capitalizeFirstLetter(key),
          dataIndex: key,
          key: key,
          render: (item) => this.props.arrayFunction(item)
        }
      }
      return {
        title: capitalizeFirstLetter(key),
        dataIndex: key,
        key: key
      }
    })
  }

  render () {
    const { tableColumns, debitorDataSource } = this.state
    return (
      <LayoutContentStyle className='details-info-container policy-detail-card'>
        <div>
          <Row>
            <h3 className='policy-title'>Debitor</h3>
            <Col span={24}>
              <Table
                pagination={{ pageSize: 100 }}
                columns={tableColumns}
                dataSource={debitorDataSource}
                scroll={{ x: true }}
              />
            </Col>
          </Row>
        </div>
      </LayoutContentStyle>
    )
  }
}

export default DebitorComponent
