import React from 'react'
import { Table, Button } from 'antd'
import TableStyleWrapper from './index.style'
import ReactJson from 'react-json-view'
import ObjectConverter from '../../../../../helpers/objectConverter'
import CustomModal from './customModal'

const WebHookTable = ({ tableData, getWehbookRetry, methods }) => {
  const { handleTableChangeFunction, totalRecordsState, pageState, perPage } = methods

  const renderColumObj = (modalTitleName, objConverter) => (
    <CustomModal buttonTitle='View' modalTitle={modalTitleName}>
      {
        typeof objConverter === 'object' && objConverter !== null
          ? (<ReactJson
              name='detail'
              src={objConverter}
              displayDataTypes={false}
              displayObjectSize={false}
              enableClipboard={false}
             />)
          : (<div className='noObject'><h3>{objConverter}</h3></div>)
      }
    </CustomModal>
  )

  const wehbookRetry = (data) => {
    getWehbookRetry({
      webhook_log_id: data?.id
    })
  }

  const columnsWebhook = [
    {
      title: 'Event Code',
      dataIndex: 'event_code',
      key: 'event_code'
    },
    {
      title: 'Reference Id',
      dataIndex: 'reference_id',
      key: 'reference_id'
    },
    {
      title: 'Request Url',
      dataIndex: 'request_url',
      key: 'request_url',
      render: (text, record) => {
        const obj = {
          url: text
        }
        const modalTitleName = `Request Url - ${record.event_code}`
        const objConverter = ObjectConverter(obj)
        return renderColumObj(modalTitleName, objConverter)
      }
    },
    {
      title: 'Request Header',
      dataIndex: 'request_header',
      key: 'request_header',
      render: (text, record) => {
        const objConverter = ObjectConverter(text)
        const modalTitleName = `Request Header - ${record.event_code}`
        return renderColumObj(modalTitleName, objConverter)
      }
    },
    {
      title: 'Request Body',
      dataIndex: 'request_body',
      key: 'request_body',
      render: (text, record) => {
        const objConverter = ObjectConverter(text)
        const modalTitleName = `Request Body - ${record.event_code}`
        return renderColumObj(modalTitleName, objConverter)
      }
    },
    {
      title: 'Response Text',
      dataIndex: 'response_text',
      key: 'response_text',
      render: (text, record) => {
        if (text) {
          const objConverter = ObjectConverter(text)
          const modalTitleName = `Response Text - ${record.event_code}`
          return renderColumObj(modalTitleName, objConverter)
        } else {
          return <h3>No Data</h3>
        }
      }
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status'
    },
    {
      title: 'Retry',
      key: 'retry',
      render: (data) => <Button onClick={() => wehbookRetry(data)}>Retry</Button>
    }
  ]
  const webHookData = !!tableData && tableData.map((val, index) => {
    return {
      key: index,
      ...val
    }
  })

  return (
    <TableStyleWrapper>
      <Table
        rowKey={record => record.id}
        scroll={{ x: true }}
        className='policy-table'
        columns={columnsWebhook}
        dataSource={webHookData}
        pagination={{
          pageSize: perPage,
          total: totalRecordsState,
          current: pageState
        }}
        onChange={handleTableChangeFunction}
      />
    </TableStyleWrapper>
  )
}
export default WebHookTable
