import React from 'react'
import { connect } from 'react-redux'
import { Modal, Button } from 'antd'
class ModalClaimConfirmation extends React.Component {
  state = {
    loading: false
  }

  handleCancel = () => {
    this.props.onCancel()
  }

  handleOk = () => {
    this.props.onOk()
  }

  render () {
    const { isOpen, message, loading } = this.props
    return (
      <Modal
        title='Initiate new claim'
        visible={isOpen}
        footer={null}
        closable={false}
        wrapClassName='benefits-modal'
        maskClosable={false}
        centered
      >
        <div className='claim-validation-content'>
          {message}
        </div>
        <div className='claim-validation-footer'>
          <Button
            className='yes-btn-claim-validation'
            onClick={this.handleOk}
            loading={loading}
          >YES
          </Button>
          <Button
            className='no-btn-claim-validation'
            onClick={this.handleCancel}
          >NO
          </Button>
        </div>
      </Modal>
    )
  }
}

export default connect(
  state => ({
    // createClaimGocarPassengerStatus: state.Claims.createClaimGocarPassengerStatus
  }),
  {}
)(ModalClaimConfirmation)
