import { useEffect } from 'react'
import { Button, Form, Input, Upload, message, Icon, Spin } from 'antd'

const FormItem = Form.Item

function PolicyDetailsCancellation (props) {
  const {
    form,
    submitModalValues,
    resetInsuranceRedux,
    closePolicyCancelModal,
    statusCancelPolicy,
    cancelPolicyLoading,
    uploadGenericPolicyFile,
    uploadPolicyFileData,
    uploadPolicyFileDataLoading
  } = props

  const { getFieldDecorator } = form

  const handleFormSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      if (!err) {
        submitModalValues(values)
      } else {
        console.log('Received values of form: ', err)
      }
    })
  }

  useEffect(() => {
    if (cancelPolicyLoading === false && statusCancelPolicy) {
      form.setFieldsValue({ document_url: '' })
      closePolicyCancelModal()
    }
  }, [statusCancelPolicy, cancelPolicyLoading])

  useEffect(() => {
    if (uploadPolicyFileData) {
      const { fileName, message: uploadPolicyFileDataMessage, url } = uploadPolicyFileData
      if (fileName === 'policyCancellation') {
        if (uploadPolicyFileDataMessage === 'success') {
          form.setFieldsValue({ document_url: url })
          resetInsuranceRedux(['uploadPolicyFileData'])
        } else {
          form.setFieldsValue({ document_url: '' })
          message.error('issue while uploading')
        }
      }
    }
  }, [
    uploadPolicyFileData
  ])

  const customRequest = (info = {}) => {
    if (info?.file?.status === 'done' || info?.file?.status === 'error') {
      const { file } = info
      const { status } = file
      if (status === 'uploading') return
      if (status === 'error') {
        message.error('File Uplaod failed')
        return
      }

      const isGt100MB = file.size / 1024 / 1024 > 100
      const uploadedFile = file.originFileObj
      const formData = new FormData()
      formData.append('file', uploadedFile)

      if (isGt100MB) {
        message.error('Note: Maximum allowed file size is 100Mb')
      } else {
        uploadGenericPolicyFile({ body: formData, fileName: 'policyCancellation' })
      }
    }
  }

  const dummyRequest = ({ file, onSuccess }) => {
    setTimeout(() => {
      onSuccess('ok')
    }, 0)
  }

  const onImageRemoveHandle = () => {
    form.setFieldsValue({ document_url: '' })
    resetInsuranceRedux(['uploadPolicyFileData'])
  }

  return (
    <Form onSubmit={handleFormSubmit}>
      <FormItem label='Reason'>
        {getFieldDecorator('reason', {
          rules: [{ required: true, message: 'Please enter reason!' }]
        })(
          <Input />
        )}
      </FormItem>

      <FormItem label='Policy cancellation Documents'>
        {getFieldDecorator('document_url', {
          rules: [{ required: false }],
          initialValue: ''
        })(
          <Spin spinning={!!uploadPolicyFileDataLoading}>
            <Upload
              disabled={!!uploadPolicyFileDataLoading}
              customRequest={dummyRequest}
              onChange={customRequest}
              onRemove={onImageRemoveHandle}
            >
              <Button>
                <Icon type='upload' /> Click to Upload
              </Button>
            </Upload>
          </Spin>
        )}
      </FormItem>
      <Button
        type='primary'
        htmlType='submit'
        disabled={!!uploadPolicyFileDataLoading}
      >
        Submit
      </Button>
    </Form>
  )
}

export default Form.create()(PolicyDetailsCancellation)
