import React from 'react'
import { Table, Button } from 'antd'
import moment from 'moment'
import TableStyleWrapper from './index.style'
import { replaceAgentAndAgencyDash } from 'opsModule/helpers'
const NotificationTable = ({ methods, tableData }) => {
  const {
    resendFunction,
    contentViewFunction,
    handleTableChangeFunction,
    notificationtotalDataState,
    totalRecordsState,
    pageState
  } = methods
  const notificationsData = tableData
  const columnsNotifications = [
    {
      title: 'Event',
      dataIndex: 'event',
      key: 'event',
      render: (text, record, index) => {
        return <p>{replaceAgentAndAgencyDash(text)}</p>
      }
    },
    {
      title: 'Action group name',
      dataIndex: 'action_group_name',
      key: 'action_group_name',
      render: (text, record, index) => {
        return <p>{replaceAgentAndAgencyDash(text)}</p>
      }
    },
    {
      title: 'Notification type',
      dataIndex: 'notification_type',
      key: 'notification_type'
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status'
    },
    {
      title: 'Remark',
      dataIndex: 'remark',
      key: 'remark'
    },
    {
      title: 'Recipient',
      dataIndex: 'recipient',
      key: 'recipient'
    },
    {
      title: 'Subject',
      dataIndex: 'subject',
      key: 'subject'
    },
    {
      title: 'Created At',
      dataIndex: 'created_at',
      key: 'created_at',
      render: (val) =>
        moment(val).add(7, 'hours').format('DD MMMM YYYY HH:mm:ss')
    },
    {
      title: 'Updated At',
      dataIndex: 'updated_at',
      key: 'updated_at',
      render: (val) =>
        moment(val).add(7, 'hours').format('DD MMMM YYYY HH:mm:ss')
    },
    {
      title: 'Content',
      dataIndex: 'content',
      render: (val) =>
        [null, ''].indexOf(val) !== -1
          ? (
              '-'
            )
          : (
            <span className='anchor' onClick={() => contentViewFunction(val)}>
              View
            </span>
            ),
      key: 'content'
    },
    {
      title: 'Action',
      dataIndex: 'delivery_id',
      key: 'delivery_id',
      render: (val, record) => (
        <Button
          disabled={
            ![
              'ERROR_IN_PROCESSING',
              'NOT_SENT',
              'ERROR_IN_SENDING',
              'ERROR_IN_DELIVERY'
            ].includes(record.status)
          }
          type='primary'
          onClick={() => resendFunction(val, record)}
        >
          Resend
        </Button>
      ),
      align: 'center'
    }
  ]
  const dataNotifications =
    !!notificationsData &&
    notificationsData.map((val, index) => {
      return {
        key: index,
        ...val
      }
    })

  return (
    <TableStyleWrapper>
      <Table
        scroll={{ x: true }}
        className='policy-table'
        columns={columnsNotifications}
        dataSource={dataNotifications}
        pagination={{
          pageSize: notificationtotalDataState,
          total: totalRecordsState,
          current: pageState
        }}
        onChange={handleTableChangeFunction}
      />
    </TableStyleWrapper>
  )
}
export default NotificationTable
